+    private List<TaskItem> FilteredTasksForStatus(string status) =>
+        allTasks
+            .Where(t => t.Status == status)
+            .Where(t => string.IsNullOrWhiteSpace(searchText)
+                || t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase))
+            .ToList();
+
+    private async Task HandleMoveTask((int TaskId, int Direction) args)
+    {
+        var task = allTasks.FirstOrDefault(t => t.Id == args.TaskId);
+        if (task is null) return;
+
+        var currentIndex = Array.IndexOf(Statuses, task.Status);
+        var newIndex = currentIndex + args.Direction;
+        if (newIndex < 0 || newIndex >= Statuses.Length) return;
+
+        var newStatus = Statuses[newIndex];
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
+            var idx = allTasks.FindIndex(t => t.Id == task.Id);
+            allTasks[idx] = task with { Status = newStatus };
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+
+    private async Task HandleAddTask((string Title, string Assignee, string Priority, DateTime DueDate, string Status) args)
+    {
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(args.Title, args.Assignee, args.Priority, args.DueDate);
+            allTasks.Add(created with { Status = args.Status });
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+}
